import "date"
d0 = date.truncate(t: now(), unit: 1d)
d1 = now()
// Revenue is integrated per hour, not summed per sample: energy = mean power
// over the hour x 1 h. Summing a per-sample revenue field made the daily
// total proportional to how many samples happened to be recorded, so an hour
// the device was only partly online was under-counted in proportion.
power = from(bucket:"telemetry")
  |> range(start: d0, stop: d1)
  |> filter(fn:(r) => r._measurement == "telemetry" and r._field == "grid_power_w")
  |> drop(columns: ["grid_status", "inverter_mode", "device_id"])
  |> aggregateWindow(every: 1h, fn: mean, createEmpty: false, timeSrc: "_start")
  |> keep(columns: ["_time", "_value"])
  |> rename(columns: {_value: "w"})
// Price comes from the market curve, not from the dispatch schedule: it is a
// fact about the day regardless of whether a schedule was loaded.
// A day can carry price points from more than one source (a real oree
// curve and the illustrative fallback both live under the same
// measurement, distinguished only by the `source` tag). Dropping the tag
// and taking last() picked between them non-deterministically, so the
// same hour could be valued at a real 11 666 or a fallback 5 499.
// Sorting by source descending puts "oree" ahead of "fallback", so the
// real market price always wins where one exists.
price = from(bucket:"telemetry")
  |> range(start: d0, stop: d1)
  |> filter(fn:(r) => r._measurement == "market_price" and r._field == "price_uah_mwh")
  |> drop(columns: ["device_id"])
  |> group(columns: ["_time"])
  |> sort(columns: ["source"], desc: true)
  |> first()
  |> group()
  |> keep(columns: ["_time", "_value"])
  |> rename(columns: {_value: "p"})
hourly = join(tables: {a: power, b: price}, on: ["_time"])
  |> map(fn:(r) => ({_time: r._time, _value: -(r.w / 1000.0) * (r.p / 1000.0)}))
hourly |> sum()

